"use strict";

var fs = require("fs");
var rng = require("rng");
var webgl = require("./webgl.js");

// 三层视差参数表。所有层共用同一套 buffer、同一次 draw call，
// 层间差异（密度/尺寸/alpha/频率区间）全部烘焙进顶点属性。
// 半径均为球壳半径 R 的比例值。
//   layer 0 暗远：最密、最小、最暗，贴在球壳外缘
//   layer 1 中等：密度/尺寸/亮度居中
//   layer 2 亮近：最疏、最大、最亮，靠近相机
var LAYERS = [
  {
    count: 14000,
    radiusMin: 0.66,
    radiusMax: 1.0,
    sizeMin: 0.01,
    sizeMax: 0.022,
    alphaMin: 0.1,
    alphaMax: 0.3,
    freqMin: 0.6,
    freqMax: 1.4
  },
  {
    count: 4500,
    radiusMin: 0.36,
    radiusMax: 0.7,
    sizeMin: 0.022,
    sizeMax: 0.05,
    alphaMin: 0.3,
    alphaMax: 0.62,
    freqMin: 0.5,
    freqMax: 1.1
  },
  {
    count: 1000,
    radiusMin: 0.1,
    radiusMax: 0.4,
    sizeMin: 0.055,
    sizeMax: 0.13,
    alphaMin: 0.65,
    alphaMax: 1.0,
    freqMin: 0.3,
    freqMax: 0.8
  }
];

var VERTICES_PER_STAR = 6;

// 距离渐隐区间（R 的比例）。
// 近端渐隐终点 0.14R 与亮近层内缘 0.10R、最大半边长 0.13R 衔接：
// 最靠近相机的大星点在扑屏前平滑变暗，而不是突然缩没或亮度断层。
var FADE_NEAR_START = 0.06;
