// jshint -W097
// jshint undef: true, unused: true
/* globals require,__dirname,Float32Array,module*/

"use strict";

var fs = require("fs");
var rng = require("rng");
var webgl = require("./webgl.js");

// 三层视差参数表。所有层共用同一套 buffer、同一次 draw call，
// 层间差异（密度/尺寸/alpha/频率区间）全部烘焙进顶点属性。
