const puppeteer = require("D:/gsb-auto/batches/pointwise-20261109/081-space-3d/A/node_modules/puppeteer-core");

const CHROME = "C:/Program Files/Google/Chrome/Application/chrome.exe";
const URL = "http://127.0.0.1:9911/index.html";

async function measure(page, hash) {
  await page.goto(URL + hash, { waitUntil: "load" });
  await new Promise((r) => setTimeout(r, 1800)); // warmup / shader compile
  return page.evaluate(async () => {
    window.__drawCalls = 0;
    const t0 = performance.now();
    const stamps = [];
    await new Promise((resolve) => {
      let frames = 0;
      function loop(t) {
        stamps.push(t);
        frames++;
        if (performance.now() - t0 >= 2500) return resolve();
        requestAnimationFrame(loop);
      }
      requestAnimationFrame(loop);
    });
    const intervals = [];
    for (let i = 1; i < stamps.length; i++) intervals.push(stamps[i] - stamps[i - 1]);
    intervals.sort((a, b) => a - b);
    const mean = intervals.reduce((a, b) => a + b, 0) / intervals.length;
    const p95 = intervals[Math.floor(intervals.length * 0.95)];
    const hudText = document.body.innerText.match(/gl errors: \d+/);
    return {
      frames: stamps.length,
      fps: +(1000 / mean).toFixed(1),
      meanMs: +mean.toFixed(2),
      p95Ms: +p95.toFixed(2),
      drawArraysTotal: window.__drawCalls,
      drawArraysPerFrame: +(window.__drawCalls / stamps.length).toFixed(2),
      glErrors: hudText ? hudText[0] : "n/a"
    };
  });
}

(async () => {
  const browser = await puppeteer.launch({
    executablePath: CHROME,
    headless: "new",
    args: [
      "--no-sandbox",
      "--disable-extensions",
      "--enable-unsafe-swiftshader",
      "--use-gl=angle",
      "--use-angle=swiftshader",
      "--window-size=1100,700"
    ]
  });
  const page = await browser.newPage();
  const consoleMessages = [];
  page.on("console", (m) => {
    if (m.type() === "error" || m.type() === "warning") consoleMessages.push(m.text());
  });
  page.on("pageerror", (e) => consoleMessages.push("PAGEERROR: " + e.message));

  // Count every GL draw call from inside the page.
  await page.evaluateOnNewDocument(() => {
    window.__drawCalls = 0;
    const proto = WebGLRenderingContext.prototype;
    const orig = proto.drawArrays;
    proto.drawArrays = function (...a) {
      window.__drawCalls++;
      return orig.apply(this, a);
    };
  });

  const near = await measure(page, "#dolly=0.35");
  const far = await measure(page, "#dolly=1.35");
  const tw0 = await measure(page, "#dolly=0.9&twinkle=0");
  const tw4 = await measure(page, "#dolly=0.9&twinkle=4");

  console.log(JSON.stringify({ near, far, tw0, tw4, consoleMessages }, null, 2));
  await browser.close();
})();

